  function edge(k, seed) { X.save(); X.strokeStyle = C.white; X.lineWidth = 14; tornWipe(X, k, seed); X.stroke(); X.strokeStyle = C.ink; X.lineWidth = 4; X.stroke(); X.restore(); }

