            {[0, 6, 12, 18, 23].map((i) => <span key={i} style={{ position: "absolute", left: X(i) - 30, top: CH + 14, fontFamily: MONO, fontSize: 15, color: C.text3 }}>{MONTHS[i]}</span>)}
