# Provisional timeline for local stills only: reuses real takes for unchanged lines, estimates the rest from word count.
import json, re, sys
old = json.load(open(sys.argv[1], encoding="utf-8")); sc = json.load(open(sys.argv[2], encoding="utf-8"))
byid = {l["say"]: l for l in old["lines"]}
t, lines, scenes = 0.0, [], []
for s in sc["scenes"]:
    s0 = t; t += s.get("pad_before", .1)
    for i, l in enumerate(s["lines"]):
        if i: t += .32
        o = byid.get(l["say"])
        if o:
            words = [{"w": w["w"], "t0": w["t0"] - o["start"] + t, "t1": w["t1"] - o["start"] + t} for w in o["words"]]; dur = o["dur"]
        else:
            ws = l["say"].split(); dur = .36 * len(ws) + .3; step = dur / len(ws)
            words = [{"w": w, "t0": t + i2 * step, "t1": t + (i2 + .8) * step} for i2, w in enumerate(ws)]
        lines.append({"id": l["id"], "scene": s["id"], "start": t, "dur": dur, "cap": l["cap"], "say": l["say"], "words": words,
                      "big": l.get("big", False), "progress": [[0, 0], [dur, 1]]})
        t += dur
    t += s.get("pad_after", .2); scenes.append({"id": s["id"], "start": s0, "end": t})
fps = old["fps"]; n = int(t * fps) + 1
env = [0.0] * n
for l in lines:
    for w in l["words"]:
        for f in range(int(w["t0"] * fps), min(n, int(w["t1"] * fps) + 1)): env[f] = .6
json.dump({"fps": fps, "bpm": old["bpm"], "duration": t, "scenes": scenes, "lines": lines, "env": env}, open(sys.argv[3], "w", encoding="utf-8"))
print("duration %.1f s" % t)
for l in lines:
    if l["scene"] == "neatlogs": print(l["id"], round(l["start"], 1), round(l["dur"], 1))

